"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["97684"],{7909(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.grupo_formulario.regra_autorreferente","status":422,"titulo":"A regra do grupo cita o pr\xf3prio grupo"},"descricao":{"codigo":"uniplus.grupo_formulario.regra_autorreferente","requisitos":["UNI-REQ-0146"],"oQueAconteceu":["A `exibicao` ou o `predicadoObrigatoriedade` de um grupo repet\xedvel cita o c\xf3digo do pr\xf3prio grupo ou o fato de um dos campos dele. Fora de uma ocorr\xeancia, o campo do grupo n\xe3o tem valor \xfanico (UNI-REQ-0146), e a exibi\xe7\xe3o e a obrigatoriedade do grupo se decidem antes das ocorr\xeancias existirem. A mensagem \xe9 \\"Uma regra do grupo cita \'`{c\xf3digo\\\\}`\', do pr\xf3prio grupo \u2014 a exibi\xe7\xe3o e a obrigatoriedade do grupo se decidem antes das ocorr\xeancias.\\", com o c\xf3digo citado.","A recusa vem na lista `errors` da resposta, com `field` igual a `grupos[i].exibicao` ou `grupos[i].predicadoObrigatoriedade`, uma entrada por regra, no mesmo lote das demais recusas da forma do grupo. Na cria\xe7\xe3o e na atualiza\xe7\xe3o de um modelo de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado.","A regra que cita um campo de grupo a partir de fora do grupo, como a exibi\xe7\xe3o de um item, \xe9 outra recusa, a de c\xf3digo `uniplus.grafo_formulario.cita_fato_de_membro_fora_do_grupo`. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Troque, na regra do grupo, o fato citado por um que o formul\xe1rio conhe\xe7a antes da posi\xe7\xe3o do grupo, ou retire a condi\xe7\xe3o. Uma condi\xe7\xe3o que depende dos campos do grupo pertence ao pr\xf3prio campo, que pode citar os campos anteriores da mesma ocorr\xeancia."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Grupo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);